 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.dts_DsclApprovalList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_DsclApprovalList')) : $c.util.getComponent('dts_DsclApprovalList');

scwin.dts_emp = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsEmp')) : $c.util.getComponent('dtsEmp');

scwin.dts_dep = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsDep')) : $c.util.getComponent('dtsDep');

scwin.dts_ApprovalCond = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_ApprovalCond')) : $c.util.getComponent('dts_ApprovalCond');

scwin.dts_DutyStatus = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_DutyStatus')) : $c.util.getComponent('dts_DutyStatus');

scwin.gDepCd = undefined; try { scwin.gDepCd = /* sdd-asis-lifecycle:begin gDepCd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.session.getUserInfo("depCd")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf11100' }); }

scwin.gEmpNo = undefined; try { scwin.gEmpNo = /* sdd-asis-lifecycle:begin gEmpNo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.session.getUserInfo("empNo")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf11100' }); }

scwin.gLdMktTp = undefined; try { scwin.gLdMktTp = /* sdd-asis-lifecycle:begin gLdMktTp — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.session.getUserInfo("market")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf11100' }); }

scwin.gDutyYn = undefined; try { scwin.gDutyYn = /* sdd-asis-lifecycle:begin gDutyYn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */js_duty/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf11100' }); }

scwin.gDutyChrg = undefined; try { scwin.gDutyChrg = /* sdd-asis-lifecycle:begin gDutyChrg — as-is 원문 본문(전환 이관 · 포팅 적용됨) */js_duty_chrg/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf11100' }); }

scwin.gJobTitle = undefined; try { scwin.gJobTitle = /* sdd-asis-lifecycle:begin gJobTitle — as-is 원문 본문(전환 이관 · 포팅 적용됨) */js_jobtitl/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf11100' }); }

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.gDate = undefined; scwin.gLdMktTp = undefined;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_attrReals();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf11100.onpageload' });
    }
};


