/**
 * @event
 * @name scwin.grd_Grid_ondblclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param row colid
 * @returns
 * @hidden N
*/
scwin.grd_Grid_ondblclick = function (row, colid) {
    try {
        /* sdd-asis-lifecycle:begin grd_Grid_ondblclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.setContnId(row);
        if (scwin.gExmptYn === 'Y') {
            scwin.gViewerStat = 'A';
        } else {
            scwin.gViewerStat = 'P';
        }
        if (colid === "DOC_TITLE") {
            $c.fil.fn_OpenNoDisclViewer(scwin.gAcptNo, scwin.gViewerStat, $c.session.getUserInfo("empNo"), $c.session.getUserInfo("depCd"), js_jobtitl, js_duty, js_duty_chrg, 'M', scwin.dts_DutyStatus);
        } else {
            if (colid === "ACPT_DDTM") {
                $c.fil.fn_OpenDisclAllList();
            } else {
                if (colid === "COM_ABBRV") {
                    $c.fil.fn_PopupCorpInfo();
                }
            }
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf11100.grd_Grid_ondblclick' }); }
};

