/**
 * @method
 * @name scwin.dts_emp_onfilter
 * @author Inswave
 * @date 2026. 09. 29
 * @param row
 * @returns
 * @hidden N
*/
scwin.dts_emp_onfilter = function (row) {
    /* sdd-asis-lifecycle:begin dts_emp_onfilter — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (scwin.gDepCd === "") {
        return true;
    } else {
        if (scwin.dts_emp.getCellData(row, "depCd") === scwin.gDepCd || scwin.dts_emp.getCellData(row, "depCd") === "") {
            return true;
        } else {
            return false;
        }
    }
    /* sdd-asis-lifecycle:end */
};

