/**
 * @method
 * @name scwin.tx_script_dts_dep
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_script_dts_dep = async function () {
    $c.util.getComponent("dma_scriptDtsDepReq").set("inputMessageId", "CODE_EMPDEP_IN");
    $c.util.getComponent("dma_scriptDtsDepReq").set("outputMessageId", "CODE_EMPDEP_OUT");
    $c.util.getComponent("dma_scriptDtsDepReq").set("For", "R");
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — DEP_CD", unresolved: "query_param:DEP_CD" };
    const sbmOptions = {
        id: "tx_script_dts_dep",
        method: "post",
        action: "/CodeAction.do",
        ref: "dma_scriptDtsDepReq",
        target: "dtsDep=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_dep_onloaderror'] === 'function') ? scwin['dts_dep_onloaderror'] : (typeof scwin['dts_dep_onfail'] === 'function') ? scwin['dts_dep_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_dep_onloadcompleted'] === 'function') ? scwin['dts_dep_onloadcompleted'] : ((typeof scwin['dts_dep_onsuccess'] === 'function') ? scwin['dts_dep_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dtsDep'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf11100.tx_script_dts_dep" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_script_dts_DsclApprovalList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_script_dts_DsclApprovalList = async function () {
    $c.util.getComponent("dma_scriptDts_DsclApprovalListReq").set("inputMessageId", "DSCLSTUDYCOND_AFF_IN");
    $c.util.getComponent("dma_scriptDts_DsclApprovalListReq").set("outputMessageId", "DSCLSTUDYLIST_AFF_OUT");
    $c.util.getComponent("dma_scriptDts_DsclApprovalListReq").set("SCREN_ID", 'ULDSTF11100.gfm');
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — ACPT_DATE, DEP_CD, EMP_NO, LD_MKT_TP, STAT_00, STAT_02, STAT_01, STAT_10, STAT_20, STAT_30, STAT_35, STAT_40, STAT_REG, AFF_STAT_00, AFF_STAT_01, AFF_STAT_10, AFF_STAT_20, AFF_STAT_30, AFF_STAT_40, UP_DEP_CD, SCREN_PROCES_TP_CD", unresolved: "query_param:ACPT_DATE,DEP_CD,EMP_NO,LD_MKT_TP,STAT_00,STAT_02,STAT_01,STAT_10,STAT_20,STAT_30,STAT_35,STAT_40,STAT_REG,AFF_STAT_00,AFF_STAT_01,AFF_STAT_10,AFF_STAT_20,AFF_STAT_30,AFF_STAT_40,UP_DEP_CD,SCREN_PROCES_TP_CD" };
    const sbmOptions = {
        id: "tx_script_dts_DsclApprovalList",
        method: "post",
        action: "/DisclosureStudyAffact.do",
        ref: "dma_scriptDts_DsclApprovalListReq",
        target: "dts_DsclApprovalList=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_DsclApprovalList_onloaderror'] === 'function') ? scwin['dts_DsclApprovalList_onloaderror'] : (typeof scwin['dts_DsclApprovalList_onfail'] === 'function') ? scwin['dts_DsclApprovalList_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_DsclApprovalList_onloadcompleted'] === 'function') ? scwin['dts_DsclApprovalList_onloadcompleted'] : ((typeof scwin['dts_DsclApprovalList_onsuccess'] === 'function') ? scwin['dts_DsclApprovalList_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_DsclApprovalList'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf11100.tx_script_dts_DsclApprovalList" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


