/**
 * @method
 * @name scwin.checkCond
 * @author Inswave
 * @date 2026. 09. 29
 * @param pReload
 * @returns
 * @hidden N
*/
scwin.checkCond = async function (pReload) {
    /* sdd-asis-lifecycle:begin fn_CheckCond — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.fil.getObjectValue(cal_edt_SrchDay).length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        $c.util.getComponent("cal_edt_SrchDay").focus();
        return;
    }
    let vStatCnt = 0;
    if (chk_chbStat00.checked === true) {
        vStatCnt++;
    }
    if (chk_chbStat02.checked === true) {
        vStatCnt++;
    }
    if (chk_chbStat01.checked === true) {
        vStatCnt++;
    }
    if (chk_chbStat10.checked === true) {
        vStatCnt++;
    }
    if (chk_chbStat20.checked === true) {
        vStatCnt++;
    }
    if (chk_chbStat30.checked === true) {
        vStatCnt++;
    }
    if (chk_chbStat35.checked === true) {
        vStatCnt++;
    }
    if (chk_chbStat40.checked === true) {
        vStatCnt++;
    }
    if (chk_chbReg.checked === true) {
        vStatCnt++;
    }
    let vAffStatCnt = 0;
    if (chk_chbAffstat00.checked === true) {
        vAffStatCnt++;
    }
    if (chk_chbAffstat01.checked === true) {
        vAffStatCnt++;
    }
    if (chk_chbAffstat10.checked === true) {
        vAffStatCnt++;
    }
    if (chk_chbAffstat20.checked === true) {
        vAffStatCnt++;
    }
    if (chk_chbAffstat30.checked === true) {
        vAffStatCnt++;
    }
    if (chk_chbAffstat40.checked === true) {
        vAffStatCnt++;
    }
    if (vStatCnt < 1 && vAffStatCnt < 1) {
        await $c.win.alert("처리현황 또는 사후심사현황을 한개 이상  선택하십시요.");
        return;
    }
    scwin.gDate = $c.fil.getObjectValue(cal_edt_SrchDay);
    if ($c.session.getUserInfo("depCd").substring(0, 1) === '2' || $c.session.getUserInfo("depCd").substring(0, 2) === '34') {
        scwin.gDepCd = $c.fil.getObjectValue(slc_cmb_TeamList);
        scwin.gEmpNo = $c.fil.getObjectValue(slc_cmb_EmpList);
    } else {
        scwin.gDepCd = "";
        scwin.gEmpNo = "";
    }
    await scwin.search(pReload);
    /* sdd-asis-lifecycle:end */
};


