*/
scwin.search = async function (pReload) {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    ShowWin_yn(scwin.grd_Grid, scwin.search_yn);
