        scwin.gLdMktTp = "4";
    }
    let url = "/DisclosureStudyAffact.do?method=listDsclApprovAffact&inputMessageId=DSCLSTUDYCOND_AFF_IN" + "&outputMessageId=DSCLSTUDYLIST_AFF_OUT" + "&ACPT_DATE=" + scwin.gDate + "&DEP_CD=" + scwin.gDepCd + "&EMP_NO=" + scwin.gEmpNo + "&LD_MKT_TP=" + scwin.gLdMktTp + "&STAT_00=" + scwin.getChkValue(chk_chbStat00) + "&STAT_02=" + scwin.getChkValue(chk_chbStat02) + "&STAT_01=" + scwin.getChkValue(chk_chbStat01) + "&STAT_10=" + scwin.getChkValue(chk_chbStat10) + "&STAT_20=" + scwin.getChkValue(chk_chbStat20) + "&STAT_30=" + scwin.getChkValue(chk_chbStat30) + "&STAT_35=" + scwin.getChkValue(chk_chbStat35) + "&STAT_40=" + scwin.getChkValue(chk_chbStat40) + "&STAT_REG=" + scwin.getChkValue(chk_chbReg) + "&AFF_STAT_00=" + scwin.getChkValue(chk_chbAffstat00) + "&AFF_STAT_01=" + scwin.getChkValue(chk_chbAffstat01) + "&AFF_STAT_10=" + scwin.getChkValue(chk_chbAffstat10) + "&AFF_STAT_20=" + scwin.getChkValue(chk_chbAffstat20) + "&AFF_STAT_30=" + scwin.getChkValue(chk_chbAffstat30) + "&AFF_STAT_40=" + scwin.getChkValue(chk_chbAffstat40) + "&UP_DEP_CD=" + js_belngdepcd;
    if (pReload !== 'Y') {
        url = url + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + $c.fil.SCREN_PROCS_TP_CD_01;
    }

    await scwin.tx_script_dts_DsclApprovalList();
    /* sdd-asis-lifecycle:end */
};


